  const handleSimulateIncident = () => {
    const units = ["EP Viana", "EP Kakila", "EP Sanza Pombo"];
    const categories: ("Agressao" | "Fuga" | "PosseIlicita" | "Indisciplina")[] = [
      "Agressao",
      "Fuga",
      "PosseIlicita",
      "Indisciplina"
    ];

    const randomUnit = units[Math.floor(Math.random() * units.length)];
    const randomCategory = categories[Math.floor(Math.random() * categories.length)];

    setDisciplinaryIncidentsData(prev =>
      prev.map(item => {
        if (item.unit === randomUnit) {
          return {
            ...item,
            [randomCategory]: item[randomCategory] + 1
          };
        }
        return item;
      })
    );

    // Publish to Institutional Event Bus
    const priorityMap = {
      Agressao: "CRITICAL",
      Fuga: "CRITICAL",
      PosseIlicita: "HIGH",
      Indisciplina: "NORMAL"
    };

    eventBus.publish({
      type: "INCIDENTE_REGISTADO",
      priority: priorityMap[randomCategory] as any,
      category: "SEGURANÇA",
      source: "GuardaPrisional",
      operator: currentOperator?.name || "Operador de Segurança",
      message: `INCIDENTE REGISTADO: Ocorrência de ${randomCategory} sinalizada em tempo real no ${randomUnit}.`,
      payload: {
        unit: randomUnit,
        type: randomCategory,
        timestamp: new Date().toISOString(),
        escalationStatus: "PENDING_MITIGATION"
      }
    });

    // Dynamic message log addition
    setGeneratedLogs(prev => [
      `[SINAL ELETRÓNICO DISCIPLINAR] Incidente de ${randomCategory} registado em ${randomUnit} às ${new Date().toLocaleTimeString()}`,
      ...prev
    ]);
  };

