  const [teamOpDraftProvince, setTeamOpDraftProvince] = useState<string>("");
  const [teamOpDraftPrisonId, setTeamOpDraftPrisonId] = useState<string>("");
  const [teamOpDraftPermissions, setTeamOpDraftPermissions] = useState<string[]>([]);
