      setTeamOpDraftLevel("");
      setTeamOpDraftProvince("Luanda");
      setTeamOpDraftPrisonId("");
      setTeamOpDraftPermissions([]);
      setTeamOpDraftSensitivity("CONFIDENCIAL");
