                      const prisonLabel = prisonObj ? prisonObj.name.replace("Estabelecimento Penitenciário de ", "EP ") : (inm.assignedPrisonId || inm.prisonId || "N/A");
                      const provLabel = inm.province || (prisonObj ? prisonObj.location.split(',')[0].trim() : "N/A");
